"""Protected inline PDF delivery and quorum correctness beyond displayed rows."""
from support import Client,sql
import json,uuid,pathlib,datetime
results=[];f=json.loads(pathlib.Path('test-results/phase6-fixture.json').read_text());tag=uuid.uuid4().hex[:8]
def check(name,ok):
 results.append({'test':name,'passed':bool(ok)});pathlib.Path('test-results/phase6-edges.json').write_text(json.dumps(results,indent=2));print(('PASS ' if ok else 'FAIL ')+name,flush=True);assert ok,name
c=Client();assert c.login('admin@example.test')[0]==200;w=next(w for w in c.req('/workspaces')[1] if w['role']=='Association Super Admin' and w['association'].startswith('Global'));c.activate(w)
code,d=c.upload('/documents','preview.pdf',pathlib.Path('test-results/phase6-certificate.pdf').read_bytes(),{'orgId':f['clubId'],'title':'Inline preview QA '+tag,'visibility':'Private'},'application/pdf');assert code==200,d
code,b,h=c.request('/documents/'+d['id']+'/download?preview=true');headers={k.lower():v for k,v in h.items()};check('protected PDF preview returns inline bytes',code==200 and b.startswith(b'%PDF') and headers.get('content-disposition')=='inline');check('preview permits same-origin frame only',headers.get('x-frame-options')=='SAMEORIGIN' and "frame-ancestors 'self'" in headers.get('content-security-policy',''));code,part,h=c.request('/documents/'+d['id']+'/download?preview=true',headers={'Range':'bytes=0-15'});check('protected preview supports actual byte ranges',code==206 and len(part)==16 and part.startswith(b'%PDF'));member=Client();member.login('member@example.test');member.activate(next(w for w in member.req('/workspaces')[1] if w['role']=='Club Member' and w['orgId']==f['clubId']));check('preview flag cannot bypass private file ACL',member.request('/documents/'+d['id']+'/download?preview=true')[0]==404)
club=sql("SELECT \"Id\" FROM \"Orgs\" WHERE \"Code\"='GC-007'");now=datetime.datetime.now(datetime.timezone.utc);code,m=c.req('/meetings','POST',{'orgId':club,'title':'Large quorum QA '+tag,'startsAt':now.isoformat(),'endsAt':(now+datetime.timedelta(hours=1)).isoformat(),'quorumMinimum':1100,'quorumPercent':0});assert code==200,m
# Isolated explicit fixture: 1,200 fictional existing-identity members, no accounts or external contacts.
sql(f"""CREATE TEMP TABLE quorum_people AS SELECT gen_random_uuid() id,n FROM generate_series(1,1200) n;
INSERT INTO "Persons" SELECT r.* FROM "Persons" p CROSS JOIN quorum_people x CROSS JOIN LATERAL jsonb_populate_record(NULL::"Persons",to_jsonb(p)||jsonb_build_object('Id',x.id,'UserId',NULL,'LegalName','Quorum QA {tag} '||x.n,'DisplayName','Quorum QA {tag} '||x.n,'SearchName','quorum qa {tag} '||x.n)) r WHERE p."Id"='{f['personId']}';
INSERT INTO "Memberships" SELECT r.* FROM "Memberships" p CROSS JOIN quorum_people x CROSS JOIN LATERAL jsonb_populate_record(NULL::"Memberships",to_jsonb(p)||jsonb_build_object('Id',gen_random_uuid(),'PersonId',x.id,'ClubId','{club}','Number','QA-Q-{tag}-'||x.n,'SourceApplicationId',NULL,'ImportRowId',NULL,'Status','Active','EndsAt',NULL)) r WHERE p."Id"=(SELECT "Id" FROM "Memberships" WHERE "PersonId"='{f['personId']}' AND "ClubId"='{f['clubId']}' AND "Status"='Active' LIMIT 1);
INSERT INTO "MeetingAttendances"("Id","TenantId","OrgId","Version","UpdatedAt","MeetingId","PersonId","Status","Rsvp","Mode","Reason","ActorId") SELECT gen_random_uuid(),'{w['tenantId']}','{club}',1,now(),'{m['id']}',id,'Present','Accepted','InPerson','Explicit large quorum test fixture','{sql("SELECT \"Id\" FROM \"Users\" WHERE \"Email\"='admin@example.test'")}' FROM quorum_people;""")
code,q=c.req('/meetings/'+m['id']+'/attendance');assert code==200,q;check('quorum counts all 1200 voters beyond display page',q['votingPresent']==1200 and q['present']==1200 and q['met']);check('attendance display remains bounded independently of quorum',len(q['rows'])==1000 and q['required']==1100)

body={'orgId':f['clubId'],'title':'Selected zone QA '+tag,'startsAt':'2026-11-18T00:00:00Z','endsAt':'2026-11-18T01:00:00Z','timeZone':'America/New_York','localStartsAt':'2026-11-18T10:00','localEndsAt':'2026-11-18T11:00'}
code,zoned=c.req('/meetings','POST',body);check('selected local zone resolves independent of browser zone',code==200 and datetime.datetime.fromisoformat(zoned['startsAt']).hour==15);check('edit form receives original zone-local times',zoned['localStartsAt']=='2026-11-18T10:00' and zoned['localEndsAt']=='2026-11-18T11:00');check('nonexistent DST local time rejected clearly',c.req('/meetings','POST',{**body,'localStartsAt':'2027-03-14T02:30','localEndsAt':'2027-03-14T04:00'})[0]==400);code,fall=c.req('/meetings','POST',{**body,'localStartsAt':'2027-11-07T01:30','localEndsAt':'2027-11-07T03:00'});check('ambiguous DST local time selects later occurrence',code==200 and datetime.datetime.fromisoformat(fall['startsAt']).hour==6)
print(str(len(results))+' Phase 6 edge checks passed')
